//
//   Phase 9 (OpenConstrainedSpan): sets currentConstrainedOut := [] (valid). ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//   Phase 1: UnconstrainedStep costs +1 step and appends at most 1 visible
//     token. EnterObservedConstrainedSpan appends 0. So |generated| grows by
//     at most 1 per iteration while steps grows by exactly 1. ✓
//   Phase 2: PenalizedConstrainedStep costs +1 step. AppendConstrainedToken
//     appends 1 visible token. EOS path appends 0. Net growth <= 1 per step. ✓
//   Phase 3: CloseSpanIfComplete costs +1 when closed (appends ">>" = 1 token,
//     steps += 1). In the else branch it costs 0; ConstrainedStep costs +1
//     (appends 1 token, steps += 1). Net growth <= 1 per step. ✓
//   Phases 4/8/9-close: CloseSpanWithinBudget postcondition gives
//     |generatedOut| <= |generated_old| + budget; we set steps += budget. ✓
//   Phase 5: same as Phase 1. ✓
//   Phases 6-7: same as Phases 2-3. ✓
//   Phase 9 open: OpenConstrainedSpan appends "<<" (1 token), steps += 1. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Write the final answer as: The answer is EXPR where EXPR is a plain arithmetic expression. Rules: (1) Use EXACTLY the variable names from the problem curly braces, without the braces. For example if the problem has {frac_1} write frac_1. (2) Use int() when multiplying by a fraction: int(n * frac). (3) Only use: variable names, numbers, +, -, *, /, (, ), int(). (4) EXPR must combine ALL relevant variables and numbers with operators, not just a single variable. Good examples: n * price - discount, int(n * frac_1 * frac_2), (n1 - n2) * rate / 60, count * (a + b + c + d)");

var steps: nat := 0;
var hasCompletedSpan: bool := false;

var freeBudget1: nat := (maxSteps * 78) / 100;
if freeBudget1 == 0 && maxSteps > 0 { freeBudget1 := 1; }

var penLimit: nat := 10;
var innerLimit1: nat := 100;

// Phase 1: Free generation, watching for "<<" via RenderedEndsWith
while steps < freeBudget1 && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases freeBudget1 - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken { break; }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg; insideConstrainedOut := ei; currentConstrainedOut := ec;
  }
}

// Phase 2: EOS-penalized constrained steps to force longer expressions
var penCount: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && penCount < penLimit
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + penLimit - penCount
{
  var cp := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next := helpers.PenalizedConstrainedStep(lm, parser, cp, currentConstrainedOut, [eosToken], 15.0, eosToken);
  steps := steps + 1;
  penCount := penCount + 1;
  if next == eosToken { break; }
  var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
  generated := ag; insideConstrainedOut := ai; currentConstrainedOut := ac;
}

// Phase 3: Normal constrained loop with completion checking
var innerCount1: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && innerCount1 < innerLimit1
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + innerLimit1 - innerCount1
{
  var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
  if closed {
    generated := cg; insideConstrainedOut := ci; currentConstrainedOut := cc;
    steps := steps + 1;
    hasCompletedSpan := true;
  } else {
    innerCount1 := innerCount1 + 1;
    var cp := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.ConstrainedStep(lm, parser, cp, currentConstrainedOut, eosToken);
    steps := steps + 1;
    if next == eosToken { break; }
    var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
    generated := ag; insideConstrainedOut := ai; currentConstrainedOut := ac;
  }
}

// Phase 4: Force close any open span with all remaining budget
if insideConstrainedOut && steps < maxSteps {
  var bud1 := maxSteps - steps;
  var wg1, wi1, wc1 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud1);
  generated := wg1; insideConstrainedOut := wi1; currentConstrainedOut := wc1;
  steps := steps + bud1;
  if !insideConstrainedOut { hasCompletedSpan := true; }
}

// Phase 5: Continue free gen if no span yet (up to 90% budget)
var freeBudget2: nat := (maxSteps * 90) / 100;
if freeBudget2 < freeBudget1 { freeBudget2 := freeBudget1; }
if freeBudget2 > maxSteps { freeBudget2 := maxSteps; }

while steps < freeBudget2 && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases freeBudget2 - steps
{
